"""Creates a GN include file for building dav2d from source."""

import datetime
import glob
import os
import re

BASE_DIR = os.path.abspath(os.path.dirname(__file__))
LIBDAV2D_DIR = os.path.join(BASE_DIR, 'libdav2d')

_COPYRIGHT = """# Copyright %d The Chromium Authors
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

# NOTE: this file is autogenerated by dav2d/generate_source.py - DO NOT EDIT.

""" % (
    datetime.datetime.now().year)


def _Glob(pattern):
    full_pattern = os.path.join(BASE_DIR, pattern)
    return [
        os.path.relpath(p, BASE_DIR).replace(os.sep, '/')
        for p in glob.glob(full_pattern)
    ]


def _WriteArray(fd, var_name, array, last_entry=False):
    if len(array) == 0:
        fd.write("%s = []\n" % var_name)
        if not last_entry:
            fd.write("\n")
        return

    fd.write("%s = [\n" % var_name)
    for item in sorted(array):
        fd.write("  \"%s\",\n" % item)
    fd.write("]\n")
    if not last_entry:
        fd.write("\n")


def _WriteGn(fd):
    meson_path = os.path.join(LIBDAV2D_DIR, 'src', 'meson.build')
    with open(meson_path, 'r', encoding='utf-8') as f:
        uncommented_lines = [line.split('#', 1)[0] for line in f]
    meson_text = '\n'.join(uncommented_lines)
    meson_entries = set(re.findall(r"'([^']+\.(?:c|S|asm))'", meson_text))

    def MesonSrcFiles(prefix, suffix):
        return [
            f'libdav2d/src/{entry}' for entry in meson_entries
            if entry.startswith(prefix) and entry.endswith(suffix)
        ]

    fd.write(_COPYRIGHT)

    _WriteArray(fd, "x86_asm_sources", MesonSrcFiles('x86/', '.asm'))
    _WriteArray(fd, "x86_template_sources", MesonSrcFiles('x86/', '_tmpl.c'))

    _WriteArray(fd, "arm32_asm_sources", MesonSrcFiles('arm/32/', '.S'))
    _WriteArray(fd, "arm64_asm_sources", MesonSrcFiles('arm/64/', '.S'))
    _WriteArray(fd, "arm_template_sources", MesonSrcFiles('arm/', '_tmpl.c'))

    riscv64_asm_sources = MesonSrcFiles('riscv/64/', '.S')
    if os.path.exists(os.path.join(LIBDAV2D_DIR, 'src', 'riscv', 'asm.S')):
        riscv64_asm_sources.append('libdav2d/src/riscv/asm.S')
    _WriteArray(fd, "riscv64_asm_sources", riscv64_asm_sources)

    top_level_c = [
        f'libdav2d/src/{entry}' for entry in meson_entries
        if '/' not in entry and entry.endswith('.c')
    ]
    template_sources = [p for p in top_level_c if p.endswith('_tmpl.c')]
    c_sources = [p for p in top_level_c if not p.endswith('_tmpl.c')]

    _WriteArray(fd, "template_sources", template_sources)

    c_headers = (_Glob("libdav2d/include/common/*.h") +
                 _Glob("libdav2d/include/dav2d/*.h") +
                 _Glob("libdav2d/src/*.h"))
    _WriteArray(fd, "c_headers", c_headers)
    _WriteArray(fd, "c_sources", c_sources, last_entry=True)


def main():
    with open(os.path.join(BASE_DIR, "dav2d_generated.gni"), "w") as fd:
        _WriteGn(fd)


if __name__ == "__main__":
    main()
